import { useAudioPlayer, type AudioPlayer } from 'expo-audio';
import { useSQLiteContext } from 'expo-sqlite';
import { useEffect, useState } from 'react';

import { readSetting } from './settings';

export type LessonSound = 'correct' | 'wrong' | 'combo' | 'complete';

/** Short lesson sounds (generated by scripts/generate-sounds.py), respecting the user's setting. */
export function useLessonSounds() {
  const db = useSQLiteContext();
  const [enabled, setEnabled] = useState(false);
  const players: Record<LessonSound, AudioPlayer> = {
    correct: useAudioPlayer(require('../../../assets/sounds/correct.wav')),
    wrong: useAudioPlayer(require('../../../assets/sounds/wrong.wav')),
    combo: useAudioPlayer(require('../../../assets/sounds/combo.wav')),
    complete: useAudioPlayer(require('../../../assets/sounds/complete.wav')),
  };

  useEffect(() => {
    let active = true;
    readSetting(db, 'lesson_sounds')
      .then((value) => {
        if (active) setEnabled(value);
      })
      // Without the setting the lesson simply stays silent.
      .catch(() => undefined);
    return () => {
      active = false;
    };
  }, [db]);

  function play(sound: LessonSound) {
    if (!enabled) return;
    const player = players[sound];
    // Sounds are a finishing touch – a failed playback must never interrupt the lesson.
    player
      .seekTo(0)
      .then(() => player.play())
      .catch(() => undefined);
  }

  return play;
}
